const nextJournalEntryNo = `-- name: NextJournalEntryNo :one
SELECT (COALESCE(MAX(entry_no), 0) + 1)::int AS next_no
FROM journal_drafts
WHERE organization_id = $1 AND engagement_id = $2 AND period = $3
`

type NextJournalEntryNoParams struct {
	OrganizationID int64  `json:"organization_id"`
	EngagementID   int64  `json:"engagement_id"`
	Period         string `json:"period"`
}

func (q *Queries) NextJournalEntryNo(ctx context.Context, arg NextJournalEntryNoParams) (int32, error) {
	row := q.db.QueryRow(ctx, nextJournalEntryNo, arg.OrganizationID, arg.EngagementID, arg.Period)
	var next_no int32
	err := row.Scan(&next_no)
	return next_no, err
}

const reverseExportBatchItem = `-- name: ReverseExportBatchItem :execrows
WITH rev AS (
    UPDATE export_batch_items SET reversed_at = NOW(), reversed_by = $3, reversal_reason = $4
    WHERE export_batch_items.organization_id = $1 AND export_batch_items.engagement_id = $2
      AND export_batch_items.journal_draft_id = $5 AND export_batch_items.reversed_at IS NULL
    RETURNING export_batch_items.journal_draft_id
)
UPDATE journal_drafts SET status = 'approved'
WHERE journal_drafts.organization_id = $1 AND journal_drafts.engagement_id = $2
  AND journal_drafts.id IN (SELECT journal_draft_id FROM rev)
`

type ReverseExportBatchItemParams struct {
	OrganizationID int64       `json:"organization_id"`
	EngagementID   int64       `json:"engagement_id"`
	ReversedBy     pgtype.Int8 `json:"reversed_by"`
	Reason         pgtype.Text `json:"reason"`
	JournalDraftID int64       `json:"journal_draft_id"`
}

// Geri alma: kim, ne zaman, neden. Fiş tekrar onaylı olur ve yeniden çıktıya alınabilir.
func (q *Queries) ReverseExportBatchItem(ctx context.Context, arg ReverseExportBatchItemParams) (int64, error) {
	result, err := q.db.Exec(ctx, reverseExportBatchItem,
		arg.OrganizationID,
		arg.EngagementID,
		arg.ReversedBy,
		arg.Reason,
		arg.JournalDraftID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

